import React from 'react';
import { Link } from 'react-router-dom';
import './BrowseByRoom.css';

const BrowseByRoom = () => {
  const rooms = [
    { name: 'Kitchen', icon: '🍳', category: 'kitchen' },
    { name: 'Bathroom', icon: '🛁', category: 'bath' },
    { name: 'Bedroom', icon: '🛏️', category: 'bedroom' },
    { name: 'Living Room', icon: '🛋️', category: 'living' },
    { name: 'Dining Room', icon: '🍽️', category: 'dining' },
    { name: 'Outdoor', icon: '🌿', category: 'outdoor' }
  ];

  return (
    <section className="browse-by-room">
      <div className="container">
        <h2 className="section-title">Browse by Room</h2>
        <p className="section-subtitle">Find inspiration for every space in your home</p>
        
        <div className="room-grid">
          {rooms.map((room, index) => (
            <Link 
              key={index} 
              to={`/photos?category=${room.category}`} 
              className="room-card"
            >
              <div className="room-icon">{room.icon}</div>
              <h3 className="room-name">{room.name}</h3>
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
};

export default BrowseByRoom;
